// ---------------------------------------------------------------------------
// Whole scenes: a planner lays out a composition (positions, facing and a
// natural-language description for every part), each part is generated by
// the regular generators (so every house, villager, tree and animal is
// unique), and the pipeline registers the parts as individual, editable
// entities owned by the scene anchor, which also paints paths and fields.
// Generation respects the time budget: when running late the planner stops
// adding optional parts.
// ---------------------------------------------------------------------------

import * as THREE from 'three';
import { G } from '../../core/context.js';
import { parseEntity } from '../nlp.js';
import { MeshBuilder } from './buildkit.js';
import { buildRock } from '../../world/trees.js';
import { obox, glowSprite, animate } from './common.js';

const TAU = Math.PI * 2;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const faceCenter = (x, z) => Math.atan2(-x, -z);

// Scene plans: arrays of { text, x, z, yaw, optional, after }.
const PLANS = {
  village(rng) {
    const parts = [{ text: 'a stone well', x: 0, z: 0 }];
    const n = rng.int(5, 7);
    const styles = ['cottage', 'medieval house', 'log cabin', 'cottage', 'farmhouse', 'medieval house', 'thatched cottage'];
    for (let i = 0; i < n; i++) {
      const an = (i / n) * TAU + rng.range(-0.15, 0.15), r = rng.range(22, 28);
      const x = Math.cos(an) * r, z = Math.sin(an) * r;
      parts.push({ text: 'a ' + styles[i % styles.length], x, z, yaw: faceCenter(x, z), path: true });
    }
    for (let i = 0; i < 4; i++) { const an = rng.range(0, TAU), r = rng.range(5, 14); parts.push({ text: rng.pick(['a villager in medieval clothes', 'an old farmer', 'a young woman in a long dress', 'a blacksmith', 'a child']), x: Math.cos(an) * r, z: Math.sin(an) * r, optional: true }); }
    parts.push({ text: 'a horse', x: rng.range(-10, 10), z: rng.range(8, 14), optional: true });
    parts.push({ text: 'a wooden wagon', x: 6, z: -6, yaw: 0.6, optional: true });
    for (let i = 0; i < 6; i++) { const an = rng.range(0, TAU), r = rng.range(34, 42); parts.push({ text: rng.pick(['an oak tree', 'a birch tree', 'a pine tree']), x: Math.cos(an) * r, z: Math.sin(an) * r, optional: true }); }
    return { name: 'Village', radius: 44, parts, paint: 'dirt' };
  },
  city(rng) {
    const parts = [];
    const block = 26;
    for (let gx = -1; gx <= 1; gx++) for (let gz = -1; gz <= 1; gz++) {
      if (gx === 0 && gz === 0) { parts.push({ text: 'a fountain', x: 0, z: 0 }); continue; }
      const x = gx * block, z = gz * block;
      const tall = Math.abs(gx) + Math.abs(gz) === 2 || rng.chance(0.4);
      parts.push({ text: tall ? rng.pick(['a glass skyscraper', 'a 20 story skyscraper', 'an art deco skyscraper', 'a futuristic tower']) : rng.pick(['a coffee shop', 'a bakery', 'a book shop', 'a 2 story shop']), x, z, yaw: faceCenter(x, z) });
    }
    for (let i = 0; i < 4; i++) parts.push({ text: rng.pick(['a yellow taxi', 'a red car', 'a blue suv', 'a white van', 'a city bus']), x: (i - 1.5) * 9, z: block / 2, yaw: Math.PI / 2, optional: true });
    for (let i = 0; i < 6; i++) parts.push({ text: 'a street lamp', x: (i % 2 ? 1 : -1) * block / 2 + 1.5, z: (Math.floor(i / 2) - 1) * block, optional: true });
    for (let i = 0; i < 4; i++) parts.push({ text: rng.pick(['a businessman in a suit', 'a woman with a handbag', 'a tourist wearing a hat', 'a teenager in a hoodie']), x: rng.range(-8, 8), z: rng.range(-8, 8), optional: true });
    return { name: 'City', radius: 50, parts, paint: 'asphalt', roads: block };
  },
  park(rng) {
    const parts = [{ text: 'a stone fountain', x: 0, z: 0 }];
    for (let i = 0; i < 4; i++) { const an = (i / 4) * TAU + TAU / 8, r = 7; const x = Math.cos(an) * r, z = Math.sin(an) * r; parts.push({ text: 'a wooden bench', x, z, yaw: faceCenter(x, z) }); }
    for (let i = 0; i < 8; i++) { const an = (i / 8) * TAU, r = rng.range(14, 19); parts.push({ text: rng.pick(['an oak tree', 'a cherry blossom tree', 'a maple tree', 'a birch tree']), x: Math.cos(an) * r, z: Math.sin(an) * r, optional: true }); }
    parts.push({ text: 'flowers', x: 10, z: 0, optional: true }, { text: 'flowers', x: -10, z: 0, optional: true });
    for (let i = 0; i < 4; i++) { const an = (i / 4) * TAU; parts.push({ text: 'a street lamp', x: Math.cos(an) * 11, z: Math.sin(an) * 11, optional: true }); }
    parts.push({ text: 'an old man reading a book', x: 5, z: 5, optional: true }, { text: 'a woman jogging in sportswear', x: -4, z: 8, optional: true }, { text: 'a friendly dog', x: -3, z: 5, optional: true });
    return { name: 'Park', radius: 22, parts, paint: 'gravelPaths' };
  },
  campsite(rng) {
    const parts = [{ text: 'a campfire', x: 0, z: 0 }];
    for (let i = 0; i < 3; i++) { const an = (i / 3) * TAU + 0.8, r = 7; const x = Math.cos(an) * r, z = Math.sin(an) * r; parts.push({ text: rng.pick(['a green tent', 'an orange tent', 'a blue tent']), x, z, yaw: faceCenter(x, z) }); }
    parts.push({ text: 'a camper wearing a flannel shirt', x: 2.8, z: 1, optional: true }, { text: 'a young woman in a jacket', x: -2.5, z: 1.5, optional: true });
    parts.push({ text: 'a white van', x: 12, z: -6, yaw: 0.8, optional: true });
    for (let i = 0; i < 7; i++) { const an = rng.range(0, TAU), r = rng.range(14, 20); parts.push({ text: rng.pick(['a pine tree', 'a spruce tree', 'a pine tree']), x: Math.cos(an) * r, z: Math.sin(an) * r, optional: true }); }
    return { name: 'Campsite', radius: 20, parts, paint: 'dirtCircle' };
  },
  farm(rng) {
    const parts = [
      { text: 'a red barn', x: -14, z: -6, yaw: 0.3 },
      { text: 'a farmhouse', x: 14, z: -8, yaw: -0.3 },
      { text: 'a tractor', x: 0, z: -4, yaw: 1.2, optional: true },
      { text: 'a hay bale', x: -6, z: 2, optional: true }, { text: 'a hay bale', x: -7.5, z: 3, optional: true },
    ];
    for (let i = 0; i < 2; i++) parts.push({ text: 'a cow', x: -10 + i * 4, z: 12 + i, optional: true });
    for (let i = 0; i < 3; i++) parts.push({ text: 'a sheep', x: 4 + i * 2.5, z: 13 + (i % 2), optional: true });
    parts.push({ text: 'a pig', x: 2, z: 6, optional: true });
    for (let i = 0; i < 4; i++) parts.push({ text: 'a chicken', x: rng.range(-4, 4), z: rng.range(1, 5), optional: true });
    parts.push({ text: 'an old farmer in overalls', x: -2, z: 0, optional: true });
    parts.push({ text: 'a wooden fence', x: -3, z: 18, optional: true }, { text: 'a wooden fence', x: 12, z: 18, optional: true });
    return { name: 'Farm', radius: 30, parts, paint: 'field' };
  },
  beach(rng) {
    const parts = [];
    for (let i = 0; i < 5; i++) parts.push({ text: 'a palm tree', x: rng.range(-16, 16), z: rng.range(-10, -4), optional: i > 1 });
    for (let i = 0; i < 2; i++) parts.push({ text: rng.pick(['a red beach umbrella', 'a blue beach umbrella']), x: -6 + i * 8, z: 2 });
    parts.push({ text: 'a beach ball', x: 1, z: 4, optional: true });
    parts.push({ text: 'a woman in a summer dress', x: -3, z: 3, optional: true }, { text: 'a man wearing shorts and sunglasses', x: 4, z: 3.5, optional: true });
    return { name: 'Beach', radius: 18, parts, paint: 'sand', prefer: 'nearWater' };
  },
  graveyard(rng) {
    const parts = [];
    for (let r = 0; r < 3; r++) for (let c = 0; c < 5; c++) parts.push({ text: 'a gravestone', x: -8 + c * 4 + rng.range(-0.3, 0.3), z: -6 + r * 4.5, yaw: rng.range(-0.1, 0.1) });
    parts.push({ text: 'a dead tree', x: -12, z: 4, optional: true }, { text: 'a dead tree', x: 11, z: -8, optional: true });
    parts.push({ text: 'a ghost', x: 2, z: 0, optional: true });
    parts.push({ text: 'an iron fence', x: 0, z: 9, optional: true });
    parts.push({ text: 'a torch', x: -3, z: 9, optional: true }, { text: 'a torch', x: 3, z: 9, optional: true });
    parts.push({ text: 'an old church', x: 0, z: -18, yaw: 0, optional: true });
    return { name: 'Graveyard', radius: 16, parts, paint: 'dirtCircle', mist: true };
  },
  livingroom(rng) {
    const parts = [
      { text: 'a sofa', x: 0, z: -2.2 }, { text: 'a coffee table', x: 0, z: -0.6 }, { text: 'a tv', x: 0, z: 2.6, yaw: Math.PI },
      { text: 'a rug', x: 0, z: -0.8 }, { text: 'a floor lamp', x: 2.3, z: -2.3 }, { text: 'a bookshelf', x: -3.3, z: 0.5, yaw: Math.PI / 2, optional: true },
      { text: 'a plant pot', x: 3.2, z: 2.4, optional: true }, { text: 'an armchair', x: 2.4, z: 0.2, yaw: -Math.PI / 2, optional: true }, { text: 'a cat', x: -1, z: 0.8, optional: true },
    ];
    return { name: 'Living room', radius: 5, parts, room: true };
  },
  kitchen(rng) {
    const H = Math.PI;
    const parts = [
      { text: 'a fridge', x: -2.6, z: -2.4 }, { text: 'an oven', x: -1.6, z: -2.5 }, { text: 'a sink', x: -0.6, z: -2.5 }, { text: 'a dishwasher', x: 0.3, z: -2.5, optional: true },
      { text: 'a kitchen counter', x: 1.4, z: -2.5, optional: true }, { text: 'a microwave', x: 1.4, z: -2.5, y: 0.92, optional: true }, { text: 'a kettle', x: 0.9, z: -2.45, y: 0.92, optional: true },
      { text: 'a table', x: 0.6, z: 0.4 }, { text: 'a chair', x: 0.6, z: -0.3 }, { text: 'a chair', x: 0.6, z: 1.1, yaw: H }, { text: 'a coffee machine', x: 1.9, z: -2.45, y: 0.92, optional: true },
      { text: 'a fruit basket', x: 0.6, z: 0.4, y: 0.76, optional: true },
    ];
    return { name: 'Kitchen', radius: 4, parts, room: true };
  },
  bathroom(rng) {
    const parts = [
      { text: 'a toilet', x: -1.4, z: -1.6 }, { text: 'a sink', x: 0, z: -1.8 }, { text: 'a mirror', x: 0, z: -1.95, y: 1.1, optional: true },
      { text: 'a shower', x: 1.5, z: -1.3 }, { text: 'a bathtub', x: -1.0, z: 1.2, yaw: Math.PI / 2, optional: true }, { text: 'a small rug', x: 0.2, z: 0.2, optional: true },
    ];
    return { name: 'Bathroom', radius: 3, parts, room: true };
  },
  bedroom(rng) {
    const parts = [
      { text: 'a bed', x: 0, z: -1.6 }, { text: 'a nightstand', x: 1.3, z: -2.3 }, { text: 'a desk lamp', x: 1.3, z: -2.3, y: 0.6, optional: true },
      { text: 'a wardrobe', x: -2.6, z: -1.2, yaw: Math.PI / 2 }, { text: 'a rug', x: 0, z: 0.6 }, { text: 'a desk', x: 2.4, z: 1.2, yaw: -Math.PI / 2, optional: true },
      { text: 'a chair', x: 1.8, z: 1.2, yaw: Math.PI / 2, optional: true }, { text: 'a plant pot', x: -2.5, z: 2.2, optional: true }, { text: 'a teddy bear', x: -0.5, z: -2.2, y: 0.6, optional: true },
    ];
    return { name: 'Bedroom', radius: 4, parts, room: true };
  },
  classroom(rng) {
    const parts = [{ text: 'a whiteboard', x: 0, z: -3.6 }, { text: 'a desk', x: 2.4, z: -2.6, yaw: Math.PI }, { text: 'a teacher', x: 1.5, z: -2.8, yaw: Math.PI, optional: true }];
    for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) { parts.push({ text: 'a small table', x: -2 + c * 2, z: -0.8 + r * 1.6, optional: r > 1 }); parts.push({ text: 'a chair', x: -2 + c * 2, z: -0.2 + r * 1.6, yaw: Math.PI, optional: r > 1 }); }
    parts.push({ text: 'a bookshelf', x: -3.8, z: 1, yaw: Math.PI / 2, optional: true }, { text: 'a globe', x: 2.6, z: -2.6, y: 0.76, optional: true });
    return { name: 'Classroom', radius: 5, parts, room: true };
  },
  officeRoom(rng) {
    const parts = [
      { text: 'a desk', x: 0, z: -1.5 }, { text: 'a computer', x: 0, z: -1.6, y: 0.76 }, { text: 'an office chair', x: 0, z: -0.8, yaw: Math.PI },
      { text: 'a filing cabinet', x: 1.6, z: -1.8 }, { text: 'a bookshelf', x: -2.2, z: -1.8, optional: true }, { text: 'a plant pot', x: 2.2, z: 1.2, optional: true },
      { text: 'a whiteboard', x: -2.6, z: 0.5, yaw: Math.PI / 2, optional: true }, { text: 'a desk lamp', x: 0.6, z: -1.7, y: 0.76, optional: true },
    ];
    return { name: 'Office', radius: 4, parts, room: true };
  },
  market(rng) {
    const parts = [];
    for (let i = 0; i < 3; i++) parts.push({ text: rng.pick(['a merchant with an apron', 'a woman carrying a basket', 'an old man with a cane']), x: rng.range(-5, 5), z: rng.range(-3, 3), optional: true });
    for (let i = 0; i < 4; i++) parts.push({ text: rng.pick(['a barrel', 'a wooden crate']), x: rng.range(-9, 9), z: rng.pick([-5, 5]), optional: true });
    return { name: 'Market', radius: 12, parts, stalls: 6, paint: 'cobble' };
  },
  zoo(rng) {
    const parts = [];
    const pens = [['a lion', -12, -8], ['an elephant', 12, -8], ['a giraffe', -12, 10], ['a zebra', 12, 10]];
    for (const [text, x, z] of pens) {
      parts.push({ text, x, z, optional: false, after: (e) => { if (e.brain) { e.brain.wanderRadius = 3; e.brain.home.copy(e.root.position); } } });
      parts.push({ text: `a sign that says "${text.replace(/^an? /, '').toUpperCase()}"`, x: x * 0.55, z: z * 0.55, yaw: faceCenter(x, z) + Math.PI, optional: true });
    }
    parts.push({ text: 'a penguin', x: 0, z: -14, optional: true }, { text: 'a penguin', x: 1, z: -14.5, optional: true });
    parts.push({ text: 'a zookeeper in a khaki uniform', x: 2, z: 2, optional: true }, { text: 'a boy with a balloon', x: -2, z: 1, optional: true });
    return { name: 'Zoo', radius: 22, parts, pens: pens.map(([, x, z]) => [x, z]), paint: 'gravelPaths' };
  },
  party(rng) {
    const parts = [
      { text: 'a table', x: 0, z: -3 }, { text: 'a birthday cake', x: 0, z: -3 },
      { text: 'colorful balloons', x: -3, z: -3, optional: true }, { text: 'colorful balloons', x: 3, z: -3, optional: true },
      { text: 'fireworks', x: 0, z: -20, optional: true },
    ];
    for (let i = 0; i < 5; i++) { const an = (i / 5) * TAU, r = 3.5; parts.push({ text: rng.pick(['a man in a party shirt', 'a woman in a sparkly dress', 'a teenager with headphones', 'a girl in a yellow dress', 'a guy with sunglasses']), x: Math.cos(an) * r, z: Math.sin(an) * r + 1, optional: true, after: (e) => { setTimeout(() => { if (e.brain) e.brain.command('dance'); }, 2500 + Math.random() * 2000); } }); }
    return { name: 'Party', radius: 10, parts, lights: true };
  },
};

function* stonehenge(ctx, rng) {
  const root = new THREE.Group();
  const b = new MeshBuilder();
  const R = 15;
  const n = 30;
  for (let i = 0; i < n; i++) {
    const an = (i / n) * TAU;
    if (rng.chance(0.2)) continue;
    const h = rng.range(3.6, 4.2), w = rng.range(1.8, 2.2);
    obox(b, 's', Math.cos(an) * R, h / 2, Math.sin(an) * R, w, h, 1.1, -an + Math.PI / 2, 0, rng.range(-0.04, 0.04));
    b.colliders.push({ type: 'box', x: Math.cos(an) * R, z: Math.sin(an) * R, y0: 0, y1: h, hx: w / 2, hz: 0.55, yaw: -an + Math.PI / 2 });
    if (i % 2 === 0 && rng.chance(0.75)) { const a2 = an + TAU / n / 2; obox(b, 's', Math.cos(a2) * R, 4.3, Math.sin(a2) * R, 3.4, 0.8, 1.0, -a2 + Math.PI / 2); }
  }
  // Inner trilithons horseshoe.
  for (let i = 0; i < 5; i++) {
    const an = Math.PI * 0.25 + (i / 4) * Math.PI * 1.5, r = 8;
    const x = Math.cos(an) * r, z = Math.sin(an) * r, h = 6 + (i === 2 ? 1.2 : 0);
    for (const s of [-1, 1]) { const px = x + Math.cos(an + Math.PI / 2) * s * 1.1, pz = z + Math.sin(an + Math.PI / 2) * s * 1.1; obox(b, 's', px, h / 2, pz, 1.6, h, 1.2, -an); b.colliders.push({ type: 'box', x: px, z: pz, y0: 0, y1: h, hx: 0.8, hz: 0.6, yaw: -an }); }
    obox(b, 's', x, h + 0.45, z, 1.2, 0.9, 4.2, -an);
  }
  obox(b, 's', 0, 0.3, 0, 4.8, 0.6, 1.2, 0.3);
  yield;
  root.add(b.build({ s: G.materials.get('stone', { color: '#a8a494', world: 3 }) }));
  return { root, name: 'Stonehenge', category: 'scene', icon: '🗿', height: 7, footprint: { radius: R + 2 }, colliderDefs: b.colliders, flattenTerrain: true, flattenFalloff: 8 };
}

function marketStall(b, x, z, yaw, rng) {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const P = (lx, lz) => [x + lx * c + lz * s, z - lx * s + lz * c];
  const w = 3, d = 1.6;
  for (const [lx, lz] of [[-w / 2, -d / 2], [w / 2, -d / 2], [-w / 2, d / 2], [w / 2, d / 2]]) { const [px, pz] = P(lx, lz); obox(b, 'wood', px, 1.2, pz, 0.1, 2.4, 0.1, yaw); }
  const [tx, tz] = P(0, d / 2 - 0.4); obox(b, 'wood', tx, 0.85, tz, w, 0.08, 0.8, yaw); obox(b, 'wood', tx, 0.42, tz, w - 0.1, 0.84, 0.05, yaw);
  const col = rng.pick(['aw1', 'aw2', 'aw3']);
  const [ax, az] = P(0, 0.1); obox(b, col, ax, 2.45, az, w + 0.3, 0.05, d + 0.8, yaw, -0.25);
  for (let i = 0; i < 5; i++) { const [gx, gz] = P(-w / 2 + 0.35 + i * 0.58, d / 2 - 0.4); obox(b, rng.pick(['fruitR', 'fruitY', 'fruitG', 'bread']), gx, 0.98, gz, 0.45, 0.18, 0.5, yaw); }
  b.colliders.push({ type: 'box', x: tx, z: tz, y0: 0, y1: 0.9, hx: w / 2, hz: 0.4, yaw });
}

export const sceneGen = {
  maxCount: 1,
  estimate: (item) => ({ city: 60, village: 60, farm: 45, zoo: 45, park: 30, campsite: 25, beach: 20, graveyard: 20, livingroom: 12, kitchen: 14, bathroom: 8, bedroom: 12, classroom: 18, officeRoom: 12, market: 18, party: 35, stonehenge: 3 }[item.params.kind] || 30),
  stages: () => [{ name: 'plan', label: 'Planning the scene', weight: 0.3 }, { name: 'geometry', label: 'Generating parts', weight: 8 }, { name: 'textures', label: 'Finishing touches', weight: 0.5 }],
  *build(ctx, item, rng, env) {
    const kind = item.params.kind;
    if (kind === 'stonehenge') return yield* stonehenge(ctx, rng);
    const { GENERATORS } = yield import('./index.js');
    const plan = (PLANS[kind] || PLANS.park)(rng);
    ctx.stage('plan', `Planning the ${plan.name.toLowerCase()}`);
    yield;
    const root = new THREE.Group();
    const b = new MeshBuilder();
    const subs = [];
    const paint = [];
    const total = plan.parts.length;
    ctx.stage('geometry', 'Generating parts');
    for (let i = 0; i < total; i++) {
      const p = plan.parts[i];
      if (p.optional && ctx.elapsed() > ctx.job.deadlineSec * 0.6) continue; // running late: skip extras
      const sub = parseEntity(p.text);
      const gen = GENERATORS[sub.gen];
      if (!gen) continue;
      const seed = rng.nextU32();
      const subRng = rng.fork('part' + i);
      const wctx = Object.create(ctx);
      wctx.stage = (name, text) => { ctx.progress(i / total, `${plan.name}: ${text || name}`); };
      wctx.progress = (f, text) => ctx.progress((i + Math.min(1, f)) / total, text ? `${plan.name}: ${text}` : undefined);
      let data;
      try { data = yield* gen.build(wctx, { ...sub, count: 1, index: 0, placement: null, seed }, subRng, env); }
      catch (err) { console.warn('[scene part failed]', p.text, err); continue; }
      if (!data) continue;
      subs.push({ data, item: sub, seed, x: p.x, z: p.z, y: p.y, yaw: p.yaw ?? rng.range(-0.5, 0.5), after: p.after });
      if (p.path && plan.paint === 'dirt') paint.push({ type: 'paint', shape: 'path', points: [[0, 0], [p.x * 0.8, p.z * 0.8]], x: 0, z: 0, radius: 1.3, channel: 1, value: 230, falloff: 0.8 });
      ctx.progress((i + 1) / total, `${plan.name}: ${data.name || sub.concept} ready`);
    }
    ctx.stage('textures', 'Finishing touches');
    yield;
    // Ground treatment & extra set pieces.
    const M = G.materials;
    const mats = { wood: M.get('wood'), aw1: M.get('stripes', { color: '#ffffff', color2: '#c81a2a', p: [8, 0.5, 0.5] }), aw2: M.get('stripes', { color: '#ffffff', color2: '#1a5ac8', p: [8, 0.5, 0.5] }), aw3: M.get('stripes', { color: '#ffffff', color2: '#2a9a3a', p: [8, 0.5, 0.5] }), fruitR: M.plain('#c81a1a', 0.5), fruitY: M.plain('#f0c020', 0.5), fruitG: M.plain('#5aa02a', 0.5), bread: M.plain('#c8883a', 0.7), floor: M.get('floorWood'), wall: M.get('paint', { color: '#e8e0d0' }), fence: M.get('wood') };
    if (plan.paint === 'dirt' || plan.paint === 'dirtCircle') paint.push({ type: 'paint', x: 0, z: 0, radius: plan.paint === 'dirt' ? 8 : plan.radius * 0.5, channel: 1, value: 200, falloff: 3 });
    if (plan.paint === 'sand') paint.push({ type: 'paint', x: 0, z: 0, radius: plan.radius, channel: 2, value: 255, falloff: 4 });
    if (plan.paint === 'cobble' || plan.paint === 'asphalt') paint.push({ type: 'paint', x: 0, z: 0, radius: plan.radius, channel: 0, value: 255, falloff: 2 });
    if (plan.paint === 'gravelPaths') { paint.push({ type: 'paint', x: 0, z: 0, radius: 9, channel: 0, value: 255, falloff: 1 }); for (let i = 0; i < 4; i++) { const an = (i / 4) * TAU; paint.push({ type: 'paint', shape: 'path', points: [[0, 0], [Math.cos(an) * plan.radius, Math.sin(an) * plan.radius]], x: 0, z: 0, radius: 1.4, channel: 0, value: 255, falloff: 0.6 }); } }
    if (plan.paint === 'field') for (let r = 0; r < 8; r++) paint.push({ type: 'paint', shape: 'rect', x: 6 + r * 1.6, z: -22, hw: 0.4, hd: 7, yaw: 0, radius: 7, channel: 1, value: 255, falloff: 0.3, alsoSuppressGrass: true });
    if (plan.roads) for (const off of [-plan.roads / 2, plan.roads / 2]) { paint.push({ type: 'paint', shape: 'rect', x: off, z: 0, hw: 4, hd: plan.radius * 1.3, yaw: 0, radius: plan.radius * 1.3, channel: 0, value: 255, falloff: 0.5, alsoSuppressGrass: true }); paint.push({ type: 'paint', shape: 'rect', x: 0, z: off, hw: plan.radius * 1.3, hd: 4, yaw: 0, radius: plan.radius * 1.3, channel: 0, value: 255, falloff: 0.5, alsoSuppressGrass: true }); }
    if (plan.stalls) for (let i = 0; i < plan.stalls; i++) { const side = i % 2 ? 1 : -1; marketStall(b, -7.5 + Math.floor(i / 2) * 5, side * 4.5, side > 0 ? Math.PI : 0, rng); }
    if (plan.pens) for (const [x, z] of plan.pens) {
      const hw = 5, hd = 5;
      for (const [ax, az, bx, bz] of [[x - hw, z - hd, x + hw, z - hd], [x + hw, z - hd, x + hw, z + hd], [x + hw, z + hd, x - hw, z + hd], [x - hw, z + hd, x - hw, z - hd]]) {
        const len = Math.hypot(bx - ax, bz - az), yaw = Math.atan2(bx - ax, bz - az);
        for (let k = 0; k <= Math.round(len / 2); k++) { const f = k / Math.round(len / 2); obox(b, 'fence', ax + (bx - ax) * f, 0.7, az + (bz - az) * f, 0.12, 1.4, 0.12, yaw); }
        for (const y of [0.45, 1.2]) obox(b, 'fence', (ax + bx) / 2, y, (az + bz) / 2, 0.06, 0.12, len, yaw);
        b.colliders.push({ type: 'box', x: (ax + bx) / 2, z: (az + bz) / 2, y0: 0, y1: 1.4, hx: 0.08, hz: len / 2, yaw, walkable: false });
      }
    }
    if (plan.room) {
      b.box({ py: 'floor', default: 'wall' }, [-4, 0, -3.2], [4, 0.1, 3.2], { collide: true });
      b.box('wall', [-4, 0.1, -3.4], [4, 3, -3.2], { collide: true });
      b.box('wall', [-4.2, 0.1, -3.4], [-4, 3, 3.2], { collide: true });
      b.box('wall', [4, 0.1, -3.4], [4.2, 3, 3.2], { collide: true });
    }
    let lights = null;
    if (plan.lights) {
      // String lights zig-zagging over the party.
      const bulbs = [];
      for (let i = 0; i < 24; i++) { const f = i / 23; const g2 = glowSprite(['#ffd070', '#ff70a0', '#70c0ff', '#a0ff70'][i % 4], 0.6, 0.9); g2.position.set(-8 + f * 16, 3.2 - Math.sin(f * Math.PI * 3) * 0.3, -1 + Math.sin(f * Math.PI * 2) * 3); root.add(g2); bulbs.push(g2); }
      animate(root, (t) => bulbs.forEach((bb, i) => { bb.material.opacity = 0.6 + 0.4 * Math.sin(t * 3 + i); }));
      lights = [{ pos: [0, 3, 0], color: '#ffc080', intensity: 3, distance: 14, nightOnly: true }];
    }
    if (plan.mist) {
      for (let i = 0; i < 16; i++) { const m = glowSprite('#c8d0d8', rng.range(4, 8), 0.12); m.material.blending = THREE.NormalBlending; m.position.set(rng.range(-14, 14), 0.6, rng.range(-12, 12)); root.add(m); }
    }
    root.add(b.build(mats));
    const data = {
      root, name: plan.name, category: 'scene', icon: item.icon, height: 3, footprint: { radius: plan.radius }, colliderDefs: b.colliders,
      suppressGrass: false, keepVegetation: plan.name === 'Park' || plan.name === 'Farm', paintGround: paint, lights, subEntities: subs, preferPlacement: plan.prefer,
    };
    return data;
  },
};
